const STUDY_TIME_KEY='learning-garden-study-time-v1',STUDY_OFFSET=19800000,STUDY_DAY=86400000;
let studyTimeState={settings:{goalMinutes:30,studyTime:'',lastLabel:''},sessions:[],activeId:''},studyTimeStorageOK=true,studyRange=7,studySelectedDay='',studyShowArchived=false;
function studyDay(ms=Date.now()){return new Date(ms+STUDY_OFFSET).toISOString().slice(0,10)}
function studyShiftDay(date,days){return new Date(Date.parse(date+'T00:00:00Z')+days*STUDY_DAY).toISOString().slice(0,10)}
function studyValidDay(date){return typeof date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(date)&&!Number.isNaN(Date.parse(date+'T00:00:00Z'))&&new Date(date+'T00:00:00Z').toISOString().slice(0,10)===date}
function studyTimestamp(n){return Number.isFinite(n)&&n>=946684800000&&n<4102444800000}
function validateStudyTime(value){if(!value||!value.settings||!Array.isArray(value.sessions)||value.sessions.length>20000)throw Error('Invalid study history');const settings=value.settings;if(!Number.isInteger(settings.goalMinutes)||settings.goalMinutes<5||settings.goalMinutes>480||typeof settings.studyTime!=='string'||settings.studyTime!==''&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(settings.studyTime))throw Error('Invalid study plan');const ids=new Set();const sessions=value.sessions.map(s=>{if(!s||typeof s.id!=='string'||ids.has(s.id)||typeof s.label!=='string'||s.label.length>120||!studyTimestamp(s.createdAt)||!studyTimestamp(s.updatedAt)||s.finishedAt!==null&&!studyTimestamp(s.finishedAt)||s.activeStart!==null&&!studyTimestamp(s.activeStart)||!Array.isArray(s.segments)||s.segments.length>10000)throw Error('Invalid study session');ids.add(s.id);let prior=0;const segments=s.segments.map(p=>{if(!p||!studyTimestamp(p.start)||!studyTimestamp(p.end)||p.end<p.start||p.start<prior)throw Error('Invalid timer segment');prior=p.end;return {start:p.start,end:p.end}});if(s.activeStart!==null&&(s.activeStart<prior||s.finishedAt!==null||s.archived))throw Error('Invalid running session');if(s.manualMs!==null&&s.manualMs!==undefined&&(!Number.isFinite(s.manualMs)||s.manualMs<=0||s.manualMs>STUDY_DAY||!studyValidDay(s.manualDate)||s.activeStart!==null))throw Error('Invalid manual duration');return {id:s.id,label:s.label,createdAt:s.createdAt,updatedAt:s.updatedAt,finishedAt:s.finishedAt,segments,activeStart:s.activeStart,manualDate:s.manualMs!=null?s.manualDate:'',manualMs:s.manualMs??null,archived:!!s.archived,source:s.source==='manual'?'manual':'timer'}});const activeId=typeof value.activeId==='string'?value.activeId:'';if(activeId&&!sessions.some(s=>s.id===activeId&&s.finishedAt===null&&!s.archived))throw Error('Invalid active session');if(sessions.some(s=>s.activeStart!==null&&s.id!==activeId))throw Error('Multiple timers');return {settings:{goalMinutes:settings.goalMinutes,studyTime:settings.studyTime,lastLabel:typeof settings.lastLabel==='string'?settings.lastLabel.slice(0,120):''},sessions,activeId}}
try{const saved=localStorage.getItem(STUDY_TIME_KEY);if(saved)studyTimeState=validateStudyTime(JSON.parse(saved))}catch{studyTimeStorageOK=false}
function persistStudyTime(){try{localStorage.setItem(STUDY_TIME_KEY,JSON.stringify(studyTimeState));studyTimeStorageOK=true}catch{studyTimeStorageOK=false}}
function activeStudySession(){return studyTimeState.sessions.find(s=>s.id===studyTimeState.activeId&&!s.archived&&s.finishedAt===null)}
function studySegments(session,now=Date.now()){return [...session.segments,...(session.activeStart!==null?[{start:session.activeStart,end:Math.max(session.activeStart,now)}]:[])]}
function studyDuration(session,now=Date.now()){return session.manualMs!==null?session.manualMs:studySegments(session,now).reduce((n,s)=>n+Math.max(0,s.end-s.start),0)}
function studyDailyTotals(sessions=studyTimeState.sessions,now=Date.now()){const totals={};for(const s of sessions){if(s.archived)continue;if(s.manualMs!==null){totals[s.manualDate]=(totals[s.manualDate]||0)+s.manualMs;continue}for(const p of studySegments(s,now)){let cursor=p.start;while(cursor<p.end){const boundary=(Math.floor((cursor+STUDY_OFFSET)/STUDY_DAY)+1)*STUDY_DAY-STUDY_OFFSET,end=Math.min(boundary,p.end),date=studyDay(cursor);totals[date]=(totals[date]||0)+end-cursor;cursor=end}}}return totals}
function studySessionDays(s,now=Date.now()){if(s.manualMs!==null)return [s.manualDate];return Object.keys(studyDailyTotals([{...s,archived:false}],now))}
function studyClock(ms){const seconds=Math.max(0,Math.floor(ms/1000));return [Math.floor(seconds/3600),Math.floor(seconds/60)%60,seconds%60].map(n=>String(n).padStart(2,'0')).join(':')}
function studyDurationText(ms){const seconds=Math.max(0,Math.floor(ms/1000)),minutes=Math.floor(seconds/60);return minutes>=60?`${Math.floor(minutes/60)}h ${minutes%60}m`:minutes>0?`${minutes}m`:seconds+'s'}
function studyStreak(totals,today=studyDay()){let day=today,count=0;if((totals[day]||0)<60000)day=studyShiftDay(day,-1);while((totals[day]||0)>=60000){count++;day=studyShiftDay(day,-1)}return count}
function studyPause(now=Date.now()){const s=activeStudySession();if(!s||s.activeStart===null)return false;if(now>s.activeStart)s.segments.push({start:s.activeStart,end:now});s.activeStart=null;s.updatedAt=now;return true}
function studyStart(label,now=Date.now()){const current=activeStudySession();if(current){if(current.activeStart===null){current.activeStart=now;current.updatedAt=now}return current}const s={id:newId(),label:label.trim().slice(0,120)||'Study session',createdAt:now,updatedAt:now,finishedAt:null,segments:[],activeStart:now,manualDate:'',manualMs:null,archived:false,source:'timer'};studyTimeState.sessions.push(s);studyTimeState.activeId=s.id;studyTimeState.settings.lastLabel=s.label;return s}
function studyFinish(now=Date.now()){const s=activeStudySession();if(!s)return null;studyPause(now);s.finishedAt=now;s.updatedAt=now;studyTimeState.activeId='';return s}
function getStudyTimeBackup(now=Date.now()){const copy=JSON.parse(JSON.stringify(studyTimeState));const s=copy.sessions.find(s=>s.id===copy.activeId);if(s&&s.activeStart!==null){if(now>s.activeStart)s.segments.push({start:s.activeStart,end:now});s.activeStart=null;s.updatedAt=now}return copy}
function mergeStudyTime(incoming){if(!incoming)return;const currentActive=activeStudySession();const map=new Map(studyTimeState.sessions.map(s=>[s.id,s]));for(const item of incoming.sessions){if(item.id===currentActive?.id)continue;let s=JSON.parse(JSON.stringify(item));if(s.activeStart!==null){s.activeStart=null;s.finishedAt=s.updatedAt}const existing=map.get(s.id);if(!existing||s.updatedAt>existing.updatedAt)map.set(s.id,s)}studyTimeState.sessions=[...map.values()];if(!currentActive&&incoming.activeId){const s=map.get(incoming.activeId);if(s&&!s.archived&&s.finishedAt===null)studyTimeState.activeId=s.id}studyTimeState.sessions.forEach(s=>{if(s.id!==studyTimeState.activeId&&s.finishedAt===null){s.activeStart=null;s.finishedAt=s.updatedAt}});persistStudyTime()}
async function changeStudyTime(action){const change=()=>{try{const raw=localStorage.getItem(STUDY_TIME_KEY);if(raw)studyTimeState=validateStudyTime(JSON.parse(raw))}catch{}action();persistStudyTime();if(view==='study')renderStudyTime();updateStudyFloating()};if(navigator.locks?.request)await navigator.locks.request('learning-garden-study-clock',change);else change()}
function studyTimeLabel(time){if(!time)return 'Choose a time that fits your day';const [h,m]=time.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'} IST`}
function renderStudyChart(now=Date.now()){const totals=studyDailyTotals(undefined,now),today=studyDay(now),days=Array.from({length:studyRange},(_,i)=>studyShiftDay(today,i-studyRange+1)),goal=studyTimeState.settings.goalMinutes;const high=Math.max(goal,...days.map(d=>(totals[d]||0)/60000),1),width=760,height=210,left=50,top=16,plotH=145,step=(width-left-12)/days.length,barW=Math.max(6,step*.63),goalY=top+plotH-goal/high*plotH;return `<svg viewBox="0 0 ${width} ${height}" class="study-chart-svg" role="group" aria-label="Daily study time for the last ${studyRange} days. Each bar can filter your session history."><text x="0" y="${top+7}" class="study-axis">${studyDurationText(high*60000)}</text><text x="16" y="${top+plotH}" class="study-axis">0m</text><line x1="${left}" y1="${top+plotH}" x2="748" y2="${top+plotH}" stroke="#dfe5dc"/><line x1="${left}" y1="${goalY}" x2="748" y2="${goalY}" stroke="#bcabc9" stroke-dasharray="4 5"/><text x="748" y="${Math.max(11,goalY-5)}" text-anchor="end" class="study-axis">${goal}m goal</text>${days.map((day,i)=>{const ms=totals[day]||0,h=ms/60000/high*plotH,x=left+i*step+(step-barW)/2;const label=new Date(day+'T12:00:00Z').toLocaleDateString('en-IN',{day:'numeric',month:'short',timeZone:'UTC'});return `<g role="button" tabindex="0" data-study-day="${day}" aria-label="${label}: ${studyDurationText(ms)}. Show sessions."><title>${label} · ${studyDurationText(ms)}</title><rect x="${x-2}" y="${top}" width="${barW+4}" height="${plotH+4}" fill="transparent"/><rect x="${x}" y="${top+plotH-Math.max(h,2)}" width="${barW}" height="${Math.max(h,2)}" rx="4" fill="${studySelectedDay===day?'#28634c':day===today?'#9bbfd8':ms>=goal*60000?'#9cb792':'#cbbbdc'}"/>${studyRange===7||i===0||i===days.length-1||i%5===0?`<text x="${x+barW/2}" y="185" text-anchor="middle" class="study-axis">${studyRange===7?new Date(day+'T12:00:00Z').toLocaleDateString('en-IN',{weekday:'short',timeZone:'UTC'}):Number(day.slice(-2))}</text>`:''}</g>`}).join('')}</svg><details class="study-table"><summary>View daily totals</summary><table><thead><tr><th>Date</th><th>Study time</th><th>Daily goal</th></tr></thead><tbody>${days.slice().reverse().map(d=>`<tr><td>${taskDate(d)}</td><td>${studyDurationText(totals[d]||0)}</td><td>${(totals[d]||0)>=goal*60000?'Met':'—'}</td></tr>`).join('')}</tbody></table></details>`}
function renderStudyTime(){const s=activeStudySession(),now=Date.now(),totals=studyDailyTotals(undefined,now),today=studyDay(now),goal=studyTimeState.settings.goalMinutes*60000;const week=Array.from({length:7},(_,i)=>studyShiftDay(today,-i)),weekMs=week.reduce((n,d)=>n+(totals[d]||0),0);$('breadcrumb').textContent='Study time';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view==='study'));$('content').innerHTML=`<div class="intro"><div><h1>Make a little time for you.</h1><p class="muted">Start small. Show up. Watch your effort add up.</p></div><button data-nav="practice">Warm up with practice ↗</button></div><div class="study-top-grid"><section class="study-clock-card"><div class="study-clock-heading"><span class="tag">${s?s.activeStart!==null?'FOCUS TIME · RUNNING':'TAKE A BREATH · PAUSED':'YOUR NEXT SMALL STEP'}</span><span class="study-clock-flower" aria-hidden="true">✳</span></div><label for="studySubject">What am I studying?</label><input id="studySubject" maxlength="120" placeholder="Kaggle · Python functions" value="${esc(s?.label||studyTimeState.settings.lastLabel)}" ${s?'disabled':''}><div class="study-clock" id="studyClock" role="timer" aria-label="Elapsed study time">${studyClock(s?studyDuration(s,now):0)}</div><p class="study-clock-caption">${s?'Your effort, one second at a time.':'A little focus can go a long way.'}</p><div class="study-clock-actions"><button id="studyToggle" class="primary">${s?s.activeStart!==null?'Pause':'Resume':'Start studying ↗'}</button><button id="studyFinish" ${!s?'disabled':''}>Finish & save</button></div><p class="learning-hint">The timer runs across tabs and refreshes until you pause or finish. Correct your log if you leave it running.</p></section><section class="study-plan-card"><h2>My daily study slot.</h2><p class="muted">A small appointment with your future self.</p><form id="studyPlanForm"><label for="studyPlanTime">My usual study time (India time)</label><input id="studyPlanTime" type="time" value="${studyTimeState.settings.studyTime}"><label for="studyPlanGoal">My daily goal (minutes)</label><input id="studyPlanGoal" type="number" min="5" max="480" step="1" required value="${studyTimeState.settings.goalMinutes}"><button class="primary" type="submit">Save my plan</button></form><p class="study-slot-label">${studyTimeLabel(studyTimeState.settings.studyTime)}</p></section></div><div class="study-stats"><div><strong id="studyTodayTotal">${studyDurationText(totals[today]||0)}</strong><span>studied today</span></div><div><strong id="studyWeekTotal">${studyDurationText(weekMs)}</strong><span>in the last 7 days</span></div><div><strong id="studyStreak">${studyStreak(totals,today)}</strong><span>day streak · 1 minute counts</span></div><div><strong id="studyGoalDays">${week.filter(d=>(totals[d]||0)>=goal).length}/7</strong><span>days meeting your goal</span></div></div><section class="study-chart-card"><div class="section-head" style="margin-top:0"><div><h2>Little by little, it adds up.</h2><p class="muted">Daily study time · ${studyTimeState.settings.goalMinutes}-minute goal</p></div><div class="study-range" role="group" aria-label="Chart range"><button data-study-range="7" class="${studyRange===7?'selected':''}">7 days</button><button data-study-range="30" class="${studyRange===30?'selected':''}">30 days</button></div></div><div id="studyChart">${renderStudyChart(now)}</div><p class="learning-hint">Updates while your timer runs. Hover or select a day to explore. Daily totals use India time.</p></section><div class="section-head"><div><h2>${studySelectedDay?'Sessions · '+taskDate(studySelectedDay):studyShowArchived?'Archived sessions':'Your study log.'}</h2>${studySelectedDay?'<button class="textbtn" id="studyClearDay">Show all days ↗</button>':''}</div><div><button class="textbtn" id="studyArchiveView">${studyShowArchived?'Current sessions':'Archived'}</button><button id="studyAddManual">＋ Add missed time</button></div></div><div id="studyLog">${renderStudyLog(now)}</div><footer><span>${studyTimeStorageOK?'Saved in this browser. Study history is included in backups.':'Storage unavailable. Export a backup to keep your study history.'}</span><span><button class="textbtn" id="export">Export backup ↓</button><button class="textbtn" id="import">Import backup ↑</button></span></footer>`;updateStudyFloating()}
function renderStudyLog(now=Date.now()){const sessions=studyTimeState.sessions.filter(s=>s.archived===studyShowArchived&&(!studySelectedDay||studySessionDays(s,now).includes(studySelectedDay))).sort((a,b)=>b.createdAt-a.createdAt);return sessions.length?`<div class="study-log-list">${sessions.slice(0,40).map(s=>`<article><div><h3>${esc(s.label)}</h3><small>${taskDate(s.manualDate||studyDay(s.createdAt))} · ${s.manualMs!==null?s.source==='manual'?'Added manually':'Time corrected':s.finishedAt?'Timer session':s.activeStart!==null?'Running':'Paused'}</small></div><strong data-study-duration="${esc(s.id)}">${studyDurationText(studyDuration(s,now))}</strong>${s.id===studyTimeState.activeId?'<span class="tag">Current</span>':`<button class="textbtn" data-study-edit="${esc(s.id)}">${s.archived?'Restore / edit':'Edit'}</button>`}</article>`).join('')}</div>${sessions.length>40?'<p class="learning-hint">Showing the latest 40 sessions. Select a chart day to narrow the list. Backups include all sessions.</p>':''}`:'<div class="study-log-empty">'+(studyShowArchived?'No archived sessions.':'Your first study session belongs here. Start the timer, or add time you already studied.')+'</div>'}
function updateStudyFloating(){let el=$('studyFloating');if(!el)return;const s=activeStudySession();el.classList.toggle('hidden',!s||view==='study');if(!s)return;const current=el.querySelector('#studyFloatingTime');current.textContent=studyClock(studyDuration(s));el.querySelector('#studyFloatingToggle').textContent=s.activeStart!==null?'Pause':'Resume';el.querySelector('#studyFloatingOpen').textContent=s.activeStart!==null?'Study timer ↗':'Study paused ↗'}
function tickStudyTime(){const s=activeStudySession();if(view==='study'&&s){const now=Date.now(),totals=studyDailyTotals(undefined,now),today=studyDay(now),week=Array.from({length:7},(_,i)=>studyShiftDay(today,-i));if($('studyClock'))$('studyClock').textContent=studyClock(studyDuration(s,now));if($('studyTodayTotal'))$('studyTodayTotal').textContent=studyDurationText(totals[today]||0);if($('studyWeekTotal'))$('studyWeekTotal').textContent=studyDurationText(week.reduce((n,d)=>n+(totals[d]||0),0));if($('studyStreak'))$('studyStreak').textContent=studyStreak(totals,today);if($('studyGoalDays'))$('studyGoalDays').textContent=week.filter(d=>(totals[d]||0)>=studyTimeState.settings.goalMinutes*60000).length+'/7';if($('studyChart')&&!$('studyChart').contains(document.activeElement)&&!$('studyChart').querySelector('details[open]'))$('studyChart').innerHTML=renderStudyChart(now);const duration=document.querySelector(`[data-study-duration="${CSS.escape(s.id)}"]`);if(duration)duration.textContent=studyDurationText(studyDuration(s,now))}updateStudyFloating()}
function studyCorrectSession(session,label,date,minutes,now=Date.now()){const prior=session?Math.max(.1,Math.round(studyDuration(session,now)/6000)/10):null;const unchanged=session&&minutes===prior&&date===(session.manualDate||studyDay(session.createdAt));const s=session||{id:newId(),createdAt:Date.parse(date+'T12:00:00+05:30'),segments:[],activeStart:null,archived:false,source:'manual'};s.label=label;if(!unchanged){s.manualDate=date;s.manualMs=Math.round(minutes*60000)}s.updatedAt=now;s.finishedAt=session?.finishedAt||now;return s}
function openStudyLogEditor(id){const s=studyTimeState.sessions.find(s=>s.id===id);if(s?.id===studyTimeState.activeId)return;const now=Date.now();$('studyEditId').value=s?.id||'';$('studyEditTitle').textContent=s?'A little correction.':'Time you already put in.';$('studyEditLabel').value=s?.label||'';$('studyEditDate').value=s?.manualDate||(s?studyDay(s.createdAt):studyDay(now));$('studyEditDate').max=studyDay(now);$('studyEditMinutes').value=s?Math.max(.1,Math.round(studyDuration(s,now)/6000)/10):'';$('studyEditError').textContent='';$('studyEditArchive').classList.toggle('hidden',!s);$('studyEditArchive').textContent=s?.archived?'Restore session':'Archive session';$('studyEditDialog').showModal()}
function setupStudyTime(){document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(['studyToggle','studyFloatingToggle'].includes(b.id)){const label=$('studySubject')?.value||studyTimeState.settings.lastLabel;await changeStudyTime(()=>{const s=activeStudySession();if(s&&s.activeStart!==null)studyPause();else studyStart(label)})}if(b.id==='studyFloatingOpen'){navigate('study');updateStudyFloating()}if(b.id==='studyFinish'){await changeStudyTime(()=>studyFinish());toast('Study session saved')}if(b.dataset.studyRange){studyRange=Number(b.dataset.studyRange);renderStudyTime()}if(b.id==='studyAddManual')openStudyLogEditor();if(b.dataset.studyEdit)openStudyLogEditor(b.dataset.studyEdit);if(b.id==='studyCloseEdit')$('studyEditDialog').close();if(b.id==='studyClearDay'){studySelectedDay='';renderStudyTime()}if(b.id==='studyArchiveView'){studyShowArchived=!studyShowArchived;studySelectedDay='';renderStudyTime()}if(b.id==='studyEditArchive'){const id=$('studyEditId').value;await changeStudyTime(()=>{const s=studyTimeState.sessions.find(s=>s.id===id);if(s&&s.id!==studyTimeState.activeId){s.archived=!s.archived;s.updatedAt=Date.now()}});$('studyEditDialog').close()}});document.addEventListener('click',e=>{const day=e.target.closest('[data-study-day]');if(day){studySelectedDay=day.dataset.studyDay;studyShowArchived=false;renderStudyTime()}});document.addEventListener('keydown',e=>{const day=e.target.closest('[data-study-day]');if(day&&['Enter',' '].includes(e.key)){e.preventDefault();studySelectedDay=day.dataset.studyDay;studyShowArchived=false;renderStudyTime()}});document.addEventListener('submit',async e=>{if(e.target.id==='studyPlanForm'){e.preventDefault();const goal=Number($('studyPlanGoal').value),time=$('studyPlanTime').value;if(!Number.isInteger(goal)||goal<5||goal>480)return;await changeStudyTime(()=>{studyTimeState.settings.goalMinutes=goal;studyTimeState.settings.studyTime=time});toast('Your study plan is saved')}if(e.target.id==='studyEditForm'){e.preventDefault();const id=$('studyEditId').value,label=$('studyEditLabel').value.trim(),date=$('studyEditDate').value,minutes=Number($('studyEditMinutes').value);if(!label||!studyValidDay(date)||date>studyDay()||!Number.isFinite(minutes)||minutes<.1||minutes>1440){$('studyEditError').textContent='Enter a title, a past or current date, and 0.1–1440 minutes.';return}await changeStudyTime(()=>{const now=Date.now(),old=studyTimeState.sessions.find(s=>s.id===id);if(old?.id===studyTimeState.activeId)return;const s=studyCorrectSession(old,label,date,minutes,now);if(!old)studyTimeState.sessions.push(s)});$('studyEditDialog').close();toast('Study time saved')}});window.addEventListener('storage',e=>{if(e.key===STUDY_TIME_KEY&&e.newValue)try{studyTimeState=validateStudyTime(JSON.parse(e.newValue));if(view==='study')renderStudyTime();updateStudyFloating()}catch{}});document.addEventListener('visibilitychange',()=>{if(!document.hidden)tickStudyTime()});setInterval(tickStudyTime,1000);updateStudyFloating()}
